export interface ConnectorConfig {
  /** Salesforce instance host, e.g. 'mycompany.my.salesforce.com' */
  instance: string
  /** OAuth access token for Salesforce REST API */
  accessToken: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface HubSpotDealWebhookPayload {
  objectId: string
  propertyChanges: Array<{ name: string; value: string }>
}

export interface UpsertResult {
  id: string
  success: boolean
  errors?: string[]
}

export interface HandleResult {
  upsertedAccountId?: string
  createdAccountId?: string
  action: 'upserted' | 'created'
}

function extractProperty(payload: HubSpotDealWebhookPayload, name: string): string | undefined {
  const change = payload.propertyChanges.find((c) => c.name === name)
  return change?.value
}

function validatePayload(payload: HubSpotDealWebhookPayload): void {
  if (!payload.objectId) throw new Error('Missing required field: objectId')
  if (!Array.isArray(payload.propertyChanges)) throw new Error('Missing required field: propertyChanges')
  const domain = extractProperty(payload, 'domain')
  if (!domain) throw new Error('Missing required property: domain')
  const dealname = extractProperty(payload, 'dealname')
  if (!dealname) throw new Error('Missing required property: dealname')
  const amount = extractProperty(payload, 'amount')
  if (!amount) throw new Error('Missing required property: amount')
}

async function upsertAccount(
  config: ConnectorConfig,
  website: string,
  body: { Name: string; Annual_Revenue__c: number }
): Promise<UpsertResult> {
  const url = `https://${config.instance}/services/data/v68.0/sobjects/Account/Website__c/${encodeURIComponent(website)}`
  const fetchFn = config.fetch ?? fetch
  const res = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })
  if (!res.ok) {
    const text = await res.text().catch(() => '')
    throw new Error(`Salesforce upsert failed: ${res.status} ${res.statusText} at PATCH ${url} - ${text}`)
  }
  return res.json() as Promise<UpsertResult>
}

async function createAccount(
  config: ConnectorConfig,
  body: { Name: string; Website__c: string; Annual_Revenue__c: number }
): Promise<UpsertResult> {
  const url = `https://${config.instance}/services/data/v68.0/sobjects/Account/`
  const fetchFn = config.fetch ?? fetch
  const res = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })
  if (!res.ok) {
    const text = await res.text().catch(() => '')
    throw new Error(`Salesforce create failed: ${res.status} ${res.statusText} at POST ${url} - ${text}`)
  }
  return res.json() as Promise<UpsertResult>
}

export async function handle(
  payload: HubSpotDealWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const domain = extractProperty(payload, 'domain')!
  const dealname = extractProperty(payload, 'dealname')!
  const amountStr = extractProperty(payload, 'amount')!
  const amount = Number(amountStr)
  if (Number.isNaN(amount)) throw new Error(`Invalid amount value: ${amountStr}`)

  const upsertBody = { Name: dealname, Annual_Revenue__c: amount }
  const createBody = { Name: dealname, Website__c: domain, Annual_Revenue__c: amount }

  try {
    const upsertResult = await upsertAccount(config, domain, upsertBody)
    if (upsertResult.success && upsertResult.id) {
      return { upsertedAccountId: upsertResult.id, action: 'upserted' }
    }
    // If upsert didn't return a successful id, fall through to create
  } catch (err) {
    // If upsert returns 300 (multiple matches) or 404 (not found), we should create
    // For other errors, rethrow
    const msg = err instanceof Error ? err.message : String(err)
    if (!msg.includes('300') && !msg.includes('404')) throw err
  }

  const createResult = await createAccount(config, createBody)
  if (!createResult.success || !createResult.id) {
    throw new Error('Salesforce create did not return a valid id')
  }
  return { createdAccountId: createResult.id, action: 'created' }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, HubSpotDealWebhookPayload, ConnectorConfig } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      instance: 'test.my.salesforce.com',
      accessToken: 'test-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.action).toBe('upserted')
    expect(result.upsertedAccountId).toBe('001XX000003DGHZAA4')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      instance: 'test.my.salesforce.com',
      accessToken: 'test-access-token',
    }
    calls = []
  })

  function makeFetch(handler: (req: RecordedCall) => Response | Promise<Response>) {
    const { fetch, calls: recorded } = fakeFetch(handler)
    calls.push(...recorded)
    return fetch
  }

  it('upserts account when domain matches existing record', async () => {
    const fetch = makeFetch((req) => {
      expect(req.method).toBe('PATCH')
      expect(req.url).toContain('/Website__c/example.com')
      expect(req.headers.get('authorization')).toBe('Bearer test-access-token')
      expect(req.json).toEqual({ Name: 'Acme Corp Deal', Annual_Revenue__c: 50000 })
      return jsonResponse({ id: '001XX000003DGHZAA4', success: true, errors: [] })
    })

    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'example.com' },
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: '50000' },
      ],
    }

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result.action).toBe('upserted')
    expect(result.upsertedAccountId).toBe('001XX000003DGHZAA4')
    expect(result.createdAccountId).toBeUndefined()
  })

  it('creates account when upsert returns 404 (no match)', async () => {
    let upsertCalled = false
    const fetch = makeFetch((req) => {
      if (req.method === 'PATCH' && req.url.includes('/Website__c/example.com')) {
        upsertCalled = true
        return jsonResponse({ error: 'Not Found' }, 404)
      }
      if (req.method === 'POST' && req.url.endsWith('/sobjects/Account/')) {
        expect(req.json).toEqual({
          Name: 'Acme Corp Deal',
          Website__c: 'example.com',
          Annual_Revenue__c: 50000,
        })
        return jsonResponse({ id: '001XX000003DGHZAA5', success: true, errors: [] })
      }
      return jsonResponse({ error: 'Unexpected' }, 500)
    })

    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'example.com' },
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: '50000' },
      ],
    }

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(upsertCalled).toBe(true)
    expect(result.action).toBe('created')
    expect(result.createdAccountId).toBe('001XX000003DGHZAA5')
  })

  it('creates account when upsert returns 300 (multiple matches)', async () => {
    let upsertCalled = false
    const fetch = makeFetch((req) => {
      if (req.method === 'PATCH' && req.url.includes('/Website__c/example.com')) {
        upsertCalled = true
        return jsonResponse({ error: 'Multiple matches found' }, 300)
      }
      if (req.method === 'POST' && req.url.endsWith('/sobjects/Account/')) {
        return jsonResponse({ id: '001XX000003DGHZAA6', success: true, errors: [] })
      }
      return jsonResponse({ error: 'Unexpected' }, 500)
    })

    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'example.com' },
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: '50000' },
      ],
    }

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(upsertCalled).toBe(true)
    expect(result.action).toBe('created')
    expect(result.createdAccountId).toBe('001XX000003DGHZAA6')
  })

  it('throws descriptive error when domain property is missing', async () => {
    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: '50000' },
      ],
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrowError(
      'Missing required property: domain'
    )
  })

