    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'example.com' },
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: 'not-a-number' },
      ],
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrowError(
      'Invalid amount value: not-a-number'
    )
  })

  it('throws error with status and endpoint on non-2xx upsert response', async () => {
    const fetch = makeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'example.com' },
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: '50000' },
      ],
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrowError(
      /Salesforce upsert failed: 401 Unauthorized at PATCH https:\/\/test\.my\.salesforce\.com\/services\/data\/v68\.0\/sobjects\/Account\/Website__c\/example\.com/
    )
  })

