    const fetch = makeFetch((req) => {
      if (req.method === 'PATCH') return jsonResponse({ error: 'Not Found' }, 404)
      return jsonResponse({ error: 'Forbidden' }, 403)
    })
    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'example.com' },
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: '50000' },
      ],
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrowError(
      /Salesforce create failed: 403 Forbidden at POST https:\/\/test\.my\.salesforce\.com\/services\/data\/v68\.0\/sobjects\/Account\//
    )
  })

  it('sends correct Authorization header on both requests', async () => {
    const fetch = makeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer test-access-token')
      if (req.method === 'PATCH') return jsonResponse({ id: '1', success: true, errors: [] })
      return jsonResponse({ id: '2', success: true, errors: [] })
    })
    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'example.com' },
        { name: 'dealname', value: 'Acme Corp Deal' },
        { name: 'amount', value: '50000' },
      ],
    }
    await handle(payload, { ...baseConfig, fetch })
  })

  it('URL-encodes the domain in upsert path', async () => {
    const fetch = makeFetch((req) => {
      if (req.method === 'PATCH') {
        expect(req.url).toContain('/Website__c/sub.domain.example.com')
        return jsonResponse({ id: '1', success: true, errors: [] })
      }
      return jsonResponse({ id: '2', success: true, errors: [] })
    })
    const payload: HubSpotDealWebhookPayload = {
      objectId: '12345',
      propertyChanges: [
        { name: 'domain', value: 'sub.domain.example.com' },
        { name: 'dealname', value: 'Test Deal' },
        { name: 'amount', value: '10000' },
      ],
    }
    await handle(payload, { ...baseConfig, fetch })
  })
})

